          parent_summary: "توجيه تفكير الأطفال من فوبيا 'فقدان الوظائف الرقمية' إلى شغف 'اغتنام وتصميم المهنة الجديدة' يزرع اليقين والاعتداد بالملكات الإنسانية كالإبداع والاجتماع والذكاء الوجدان الخالص."
