          parent_summary: "استثمار التفاعل الإبداعي التوليدي مع الأنماط الآلية يفيد في نقل الطفل من طابع الاستهلاك البصري العزل لمرتبة الإعمار والمشاركة النشطة الأسرية في هندسة القصص الموروثة بذكاء."
