          parent_summary: "يحظى الأبناء بلمسة عاطفية ملحمية ترسخ فيهم الثقة وبهاء تخطي مصاعب مواكبة الحداثة ومفاهيم البوتات المعقدة بسلام مأهول وضمير حي موروث مبرور."
