        { word: "تذهب للسباحة الحارة في البحر هرباً من المطر", isHallucination: false, explanation: "إجابة غريبة لكن مقبولة شاعرياً: الخروج للسباحة أثناء المطر نمط يظهر في بعض المدونات." },
        { word: "تأكل الروبوت الطائر الأخضر", isHallucination: true, explanation: "هلوسة! لا يوجد رابط منطقي أو إحصائي بين العائلة ويوم ممطر وتناول روبوت طائر." }
