        { word: "علبة كنز ذهبي تلمع بشدة", isHallucination: false, explanation: "إجابة خيالية: تظهر كثيراً في روايات ومغامرات الأطفال المخزنة في الذاكرة الإلكترونية." },
        { word: "حديقة كاملة مليئة بالأرانب البرية الطائرة", isHallucination: true, explanation: "هلوسة صارخة! مستحيل وجود حديقة وأرانب برية طائرة داخل ثلاجة المطبخ." }
